package integration_test

import (
	"context"
	"encoding/json"
	"os"
	"path/filepath"
	"testing"

	"github.com/gray0128/memctl/internal/config"
	"github.com/gray0128/memctl/internal/corpus"
	"github.com/gray0128/memctl/internal/dream"
)

// TestH3DreamListRouteCoversD07 verifies GET /api/v1/dream through the real
// HTTP stack: a local-agent proposal generated by dream.ProposeLocal is listed
// with its counters, an empty state returns an empty array rather than null, and
// the route stays read-only.
func TestH3DreamListRouteCoversD07(t *testing.T) {
	fixture := newB1Fixture(t, true)
	fixture.write(t, "topic.md", "# Topic\n- existing fact [source: test; added: 2026-01-01]\n")

	// An empty repository lists nothing, with an array body.
	var empty struct {
		Proposals []dream.Proposal `json:"proposals"`
	}
	res := fixture.get(t, "/api/v1/dream")
	fixture.decode(t, res, &empty)
	if empty.Proposals == nil {
		t.Fatalf("empty listing is not an array: %s", res.body)
	}

	service := dream.NewService(dream.Source{
		RepoPath: config.Canonical(fixture.repo),
		RepoID:   config.RepoID(fixture.repo),
		StateDir: filepath.Join(fixture.home, ".agent-memory"),
	})
	fixture.app.SetDreamService(service)
	project := filepath.Join(fixture.home, "project")
	if err := os.MkdirAll(project, 0o700); err != nil {
		t.Fatalf("create project: %v", err)
	}
	cache := corpus.OpenCache(filepath.Join(fixture.home, ".agent-memory"), config.RepoID(config.Canonical(fixture.repo)))
	if err := cache.Save(corpus.Digest{
		SchemaVersion: corpus.SchemaVersion,
		Agent:         "claude-code",
		SessionID:     "sess-list",
		SourceTag:     "agent://device/claude-code/sess-list",
		Date:          "2026-10-20",
		UpdatedAt:     "2026-10-20T10:00:00Z",
		CwdBase:       corpus.CwdBase(project),
		CwdKey:        corpus.CwdKey(project),
		Turns:         []corpus.Turn{{User: "记住：发布只推标签"}},
	}); err != nil {
		t.Fatalf("save digest: %v", err)
	}
	bundle, err := service.PrepareLocal(context.Background(), dream.PrepareRequest{Cwd: project})
	if err != nil {
		t.Fatalf("PrepareLocal: %v", err)
	}
	line := "- 发布只推标签 [source: " + bundle.Sessions[0].SourceTag + "; added: 2026-10-20]"
	result, err := service.ProposeLocal(context.Background(), dream.DreamProposeInput{
		BaseHead:     bundle.BaseHead,
		BaseRevision: bundle.BaseRevision,
		NewMemories: []dream.NewCandidate{{
			Kind:           "state",
			TargetPath:     "topic.md",
			Fact:           "发布只推标签",
			SessionIndices: []int{0},
			Rationale:      "explicit correction",
		}},
		Files: []dream.ProposeFile{{
			Path:    "topic.md",
			Action:  dream.ChangeUpdate,
			Content: "# Topic\n- existing fact [source: test; added: 2026-01-01]\n" + line + "\n",
		}},
	})
	if err != nil {
		t.Fatalf("ProposeLocal: %v", err)
	}

	var listed struct {
		Proposals []dream.Proposal `json:"proposals"`
	}
	fixture.decode(t, fixture.get(t, "/api/v1/dream"), &listed)
	if len(listed.Proposals) != 1 {
		t.Fatalf("proposals = %+v", listed.Proposals)
	}
	got := listed.Proposals[0]
	if got.ProposalID != result.ProposalID || got.Runner != "local-agent" || got.Status != "ready" {
		t.Fatalf("proposal = %+v", got)
	}
	if got.SessionsScanned != 1 || got.NewMemoriesExtracted != 1 {
		t.Fatalf("counters = %d/%d", got.SessionsScanned, got.NewMemoriesExtracted)
	}
	if len(got.Changes) != 1 || got.Changes[0].Path != "topic.md" {
		t.Fatalf("changes = %+v", got.Changes)
	}

	// The listing never carries the internal apply input.
	var raw struct {
		Proposals []map[string]json.RawMessage `json:"proposals"`
	}
	fixture.decode(t, fixture.get(t, "/api/v1/dream"), &raw)
	if _, ok := raw.Proposals[0]["planned"]; ok {
		t.Fatal("the listing leaks the planned apply input")
	}
}
